class Cupo {
public:
    int usados() const;
    bool reservar(int cantidad);
    bool mover_a(Cupo& destino, int cantidad);
private:
    int usados_ = 0;
};
int Cupo::usados() const {
    return usados_;
}

bool Cupo::reservar(int cantidad) {
    if (cantidad <= 0 || cantidad > 6 - usados_) {
        return false;
    }
    usados_ += cantidad;
    return true;
}
bool Cupo::mover_a(Cupo& destino, int cantidad) {
    if (this == &destino || cantidad <= 0 || cantidad > usados_) {
        return false;
    }
    usados_ -= cantidad;
    if (cantidad > 6 - destino.usados_) {
        return false;
    }
    destino.usados_ += cantidad;
    return true;
}

int main() {
    Cupo a;
    Cupo b;
    a.reservar(4);
    b.reservar(5);
    const bool aceptado = a.mover_a(b, 2);
    std::cout << aceptado << ':' << a.usados() << ':' << b.usados();
    return 0;
}

